text:
{
  "title": "استمارة طلب توظيف وإقرار معالجة البيانات - شركة الأفق المتقدم للتقنية",
  "planted": [
    {
      "slot": "p1",
      "text": "نطلب الفحوصات الطبية المتقدمة والبيانات الحيوية لجميع المتقدمين لضمان ملاءمتهم العامة لبيئة العمل، ويتم تداول هذه المعلومات بين الأقسام المعنية حسب الحاجة التشغيلية."
    },
    {
      "slot": "p2",
      "text": "نحتفظ بملفات المرشحين وبياناتهم طالما كانت هناك حاجة إدارية محتملة للمستقبل، ما لم تُطالب الجهات الرسمية بإتلافها في حالات محددة."
    },
    {
      "slot": "p3",
      "text": "تعتبر تقديم استمارة الطلب موافقة ضمنية على معالجة البيانات واستخدامها لأغراض التوظيف والمراسلات اللاحقة، مع إمكانية مراجعة الإدارة في حال الرغبة بتعديل حالة الطلب."
    }
  ],
  "neutral": [
    "تُعرّف الشركة في هذا المستند بجهة العمل، ويُقصد بالمتقدم كل من يملأ هذه الاستمارة بغرض التوظيف.",
    "تخضع كافة النزاعات الناشئة عن هذا المستند للأنظمة المعمول بها في المملكة العربية السعودية.",
    "تظل هذه الشروط سارية المفعول طوال مدة دراسة الطلب وحتى إشعار آخر.",
    "لا تتحمل الشركة أي مسؤولية عن أي أخطاء مطبعية أو تقنية تحدث أثناء إرسال المستندات.",
    "تلتزم الأطراف بتبادل الإشعارات الرسمية عبر العناوين المحددة في بداية الاستمارة.",
    "تظل جميع الحقوق الفكرية والتصاميم الخاصة بنماذج الشركة مملوكة لها حصرياً.",
    "لا توجد أي رسوم مالية مترتبة على تقديم هذا الطلب في مراحله الأولى.",
    "تتم عملية تسليم المستندات الإضافية عبر البوابة الإلكترونية المخصصة للتوظيف حصراً."
  ]
}
